  "atomic_questions": [
    "When a worker is in their 2-week training period, are they completely unavailable for production (i.e., they contribute 0 kg/h to foods I and II during both training weeks)?"
  ],
  "rationale": "The response contains a single clarification question asking whether workers contribute zero production during training."
}

